// ===== EDITE AQUI: nome da coluna da loja (igual ao cabecalho da planilha) => ID da loja no Bling =====
const LOJAS = {
  '3.3 - Seu Fetiche - E-commerce': 205023189,
  '2.3 - Surpresinhas - E-commerce': 204127665,
  '1.1 - Sigilo - E - commerce': 204636452,
  '1.1.1 Sigilo E-commerce Bagy': 205640286,
  '1.2 - Sigilo Santa Felicidade': 203466110,
  '1.3 - Whats Sigilo Entrega - Santa Felicidade': 204265522,
  '1.4 - Whats Sigilo Retirada - Santa Felicidade': 204266326,
  '2.31 IFOOD SURPRESINHAS.': 205351792,
  '2.4 - Whats Surpresinhas Entrega / Retirada - Central': 204266330,
  '5 - Mercado Livre MHB': 205134455,
  '5 - Mercado Livre SPH': 206096286,
  '5.4 - Edu Vilar ML': 204279939,
  '5.1 - Amazon MHB': 204974626,
  '5.3 - Shopee': 205333022,
  '5.6.1 - TEMU SPH': 206092323,
  '5.6.2 - TEMU MHB': 206095548,
  '2.5 - TIKTOK SURPRESINHAS': 206098011,
  '5.5 - MAGALU MHB': 205474577,
  'DROPI_2025': 205381775,
};
// ======================================================================================================

const entrada = $('Recebe produto').first().json;
const linha = $('Busca precos na planilha').first().json;

if (!linha.SKU) {
  throw new Error(`SKU "${entrada.codigo}" nao encontrado na aba "Planilha modelo".`);
}

// ID do produto: o que veio do cadastrador ou, se vazio, a coluna IdProduto da planilha
const idProduto = Number(entrada.idProduto || linha.IdProduto);
if (!idProduto) {
  throw new Error(`O SKU "${linha.SKU}" ainda nao tem IdProduto do Bling.`);
}

// compara nomes de coluna sem diferenca de maiusculas/minusculas e espacos
function normalizar(texto) {
  return String(texto).toLowerCase().replace(/\s+/g, ' ').trim();
}
const colunas = {};
for (const nome in linha) colunas[normalizar(nome)] = linha[nome];

function lerPreco(valor) {
  if (typeof valor === 'number') return valor;
  let texto = String(valor).replace('R$', '').replace(/\s/g, '');
  if (texto.includes(',')) texto = texto.replace(/\./g, '').replace(',', '.');
  return Number(texto);
}

// lojas em que o produto ja esta vinculado (para nao repetir)
const jaVinculadas = new Set(
  ($input.first().json.data || [])
    .filter(v => Number(v.produto && v.produto.id) === idProduto)
    .map(v => Number(v.loja && v.loja.id))
);

const saida = [];
for (const nomeLoja in LOJAS) {
  const chave = normalizar(nomeLoja);
  if (!(chave in colunas)) {
    throw new Error(`A coluna "${nomeLoja}" nao existe na planilha. Confira o nome no no "Monta vinculos".`);
  }
  if (jaVinculadas.has(LOJAS[nomeLoja])) continue; // ja vinculado, pula
  const valor = colunas[chave];
  if (valor === '' || valor === null || valor === undefined) continue; // sem preco = nao vende nessa loja
  const preco = lerPreco(valor);
  if (!preco) {
    throw new Error(`Preco invalido na coluna "${nomeLoja}": ${valor}`);
  }
  saida.push({
    json: {
      codigo: String(linha.SKU),
      preco: preco,
      produto: { id: idProduto },
      loja: { id: LOJAS[nomeLoja] }
    }
  });
}

return saida;
